import { useState, useRef } from "react";
import clsx from "clsx";
import { useGSAP } from "../hooks/useGSAP";
import { ParticleCanvas, Typewriter, SkillBar, Modal, ParallaxElement, ScrollReveal } from "../components/Shared";
import { DevBadge } from "../components/DeveloperMode";
import { PROJECTS, SKILLS, TECH, SERVICES, TIMELINE, CONTACT_INFO } from "../data/content";

// ── Project Card Component ───────────────────────────────────────────────────
function ProjectCard({ project, theme, onSelect }) {
  const [hovered, setHovered] = useState(false);
  const [tilt, setTilt] = useState({ x: 0, y: 0 });
  const ref = useRef(null);

  const handleMouseMove = (e) => {
    const rect = ref.current.getBoundingClientRect();
    setTilt({
      x: ((e.clientY - rect.top - rect.height / 2) / rect.height) * -4,
      y: ((e.clientX - rect.left - rect.width / 2) / rect.width) * 4
    });
  };

  return (
    <div 
      ref={ref} 
      onMouseEnter={() => setHovered(true)} 
      onMouseLeave={() => { setHovered(false); setTilt({ x: 0, y: 0 }); }} 
      onMouseMove={handleMouseMove} 
      onClick={() => onSelect(project)} 
      style={{
        width: "100%",
        background: hovered ? theme.surface : theme.surfaceAlt,
        border: `1px solid ${hovered ? theme.borderMid : theme.border}`,
        borderRadius: 16,
        overflow: "hidden",
        cursor: "pointer",
        transform: hovered 
          ? `perspective(700px) rotateX(${tilt.x}deg) rotateY(${tilt.y}deg) translateY(-4px)` 
          : "perspective(700px) rotateX(0) rotateY(0)",
        transition: "all .3s",
        boxShadow: hovered ? theme.shadowMd : theme.shadow
      }}
    >
      {/* Card Top — Background Area */}
      <div style={{ 
        height: 320, 
        background: project.image ? `url(${project.image}) center/cover no-repeat` : project.cardBg, 
        display: "flex", 
        flexDirection: "column",
        alignItems: "center", 
        justifyContent: "center",
        position: "relative",
        padding: "0 40px"
      }}>
        {/* LIVE Badge */}
        <div style={{
          position: "absolute",
          top: 20,
          right: 20,
          display: "flex",
          alignItems: "center",
          gap: 8,
          background: "rgba(0,0,0,0.4)",
          backdropFilter: "blur(10px)",
          padding: "6px 12px",
          borderRadius: 6,
